function Select({ children }) {
  const [isOpen, setIsOpen] = useState(false);
  const [selected, setSelected] = useState(null);

  return (
    <SelectContext.Provider value={{ isOpen, setIsOpen, selected, setSelected }}>
      <div className="select">{children}</div>
    </SelectContext.Provider>
  );
}

function SelectTrigger({ children }) {
  const { setIsOpen } = useContext(SelectContext);
  return <button onClick={() => setIsOpen(true)}>{children}</button>;
}

function SelectOptions({ children }) {
  const { isOpen } = useContext(SelectContext);
  return isOpen ? <ul className="options">{children}</ul> : null;
}

function SelectOption({ value, children }) {
  const { setSelected, setIsOpen } = useContext(SelectContext);
  return <li onClick={() => { setSelected(value); setIsOpen(false); }}>{children}</li>;
}

// Attach as properties
Select.Trigger = SelectTrigger;
Select.Options = SelectOptions;
Select.Option = SelectOption;
